<?php $view->extend('layouts.public');$view->section('content');?><section class="aho-pages-hero"><div class="aho-container"><h1>Mobile Buildlerim</h1><p>APK, AAB, PWA ve kaynak kod build geçmişiniz.</p></div></section><section class="aho-pages-body"><div class="aho-container"><div class="aho-card" style="padding:0;overflow:auto"><table style="width:100%;border-collapse:collapse"><thead><tr><th style="padding:12px;text-align:left">#</th><th style="padding:12px">Tür</th><th style="padding:12px">Durum</th><th style="padding:12px">İlerleme</th><th style="padding:12px">Tarih</th><th style="padding:12px"></th></tr></thead><tbody><?php foreach($jobs as $job):?><tr data-mobile-job="<?= (int)$job['id']?>" style="border-top:1px solid var(--aho-color-border)"><td style="padding:12px">#<?= (int)$job['id']?></td><td style="padding:12px"><?=e(strtoupper($job['build_type']))?></td><td style="padding:12px"><?=e($job['status'])?></td><td style="padding:12px">%<?= (int)$job['progress']?></td><td style="padding:12px"><?=e($job['created_at']??'')?></td><td style="padding:12px"><?php if(!empty($job['artifact_path'])&&$job['status']==='completed'):?><a class="aho-btn aho-btn--sm aho-btn--primary" href="/mobile-build/<?= (int)$job['id']?>/indir">İndir</a><?php else:?>Hazırlanıyor<?php endif;?></td></tr><?php endforeach;?></tbody></table><?php if(!$jobs):?><div style="padding:40px;text-align:center">Henüz Mobile Builder build işleminiz yok.</div><?php endif;?></div></div></section><script>setInterval(()=>{document.querySelectorAll('[data-mobile-job]').forEach(async row=>{try{const r=await fetch('/panel/mobile-build/'+row.dataset.mobileJob+'/status');const d=await r.json();if(d.ok){const cells=row.children;if(cells[2])cells[2].textContent=d.job.status;if(cells[3])cells[3].textContent='%'+d.job.progress;}}catch(e){}})},30000);</script><?php $view->endSection();?>